{
  "headline": "FDA's records trace our supply to a plant classified OAI 22 days before the posting",
  "headline_cites": ["E25", "D6"],
  "sentences": [
    {
      "text": "The shortage has been on FDA's list since 2021-09-23, totaling 61 months as of 2026-10-21.",
      "cites": ["D6"]
    },
    {
      "text": "A registered plant on our product labels, Baxter Healthcare Corporation (FEI 1416980), received an OAI classification on 2026-04-02.",
      "cites": ["E25", "E28"]
    },
    {
      "text": "That OAI inspection occurred 22 days before the posting date of 2026-04-02.",
      "cites": ["E25"]
    },
    {
      "text": "A subsequent Warning Letter was issued to the same plant on 2026-09-29.",
      "cites": ["E26"]
    },
    {
      "text": "Corvale East has 12 days on hand and Corvale General has 13 days on hand at current usage rates.",
      "cites": ["D1", "D2"]
    },
    {
      "text": "The rule's best option is to buy from Fresenius Kabi USA, LLC, which is not on FDA's shortage list today and whose plant last received a VAI classification on 2023-10-13.",
      "cites": ["D3"]
    }
  ]
}
